#include "display.h"
#include "mgnd_view.hpp"

// GND-SIN: generated by tools/make_engine.py. The screen: md_rig.hpp draws the
// design's parts from art.h; voices/mgnd_view.hpp draws what changes shape.
namespace mmsin {
inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion};
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[0], input.slots, moment);
    md::gnd_sin::view(frame, input.slots, moment);
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 0) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 1) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 2) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 3) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 4) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 5) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
    for (u32 i = 0; i < 4; ++i)
        if (input.shown[i] == 6) opxy::draw::copy(frame.header[i], opxy::draw::header_capacity, " ");
}
}
